import ast
import logging
import operator
from typing import Any

log = logging.getLogger(__name__)

_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}


class rules_Engine:
    """Evaluates customer-defined rules expressions."""

    def __init__(self, context: dict[str, Any]):
        self.context = context

    def _eval_node(self, node):
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            return self.context[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in _OPS:
            return _OPS[type(node.op)](self._eval_node(node.left), self._eval_node(node.right))
        raise ValueError("unsupported expression")

    def apply_pricing(self, expression: str) -> Any:
        log.debug("evaluating %s", expression)
        if not expression.strip():
            return None
        return self._eval_node(ast.parse(expression, mode="eval").body)

